const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
let lastY=0;addEventListener('scroll',()=>{const y=scrollY;$('.nav').classList.toggle('scrolled',y>40);$('.nav').classList.toggle('away',y>lastY&&y>500&&!$('.menu-toggle').getAttribute('aria-expanded').includes('true'));$('.scroll-progress').style.width=`${y/(document.documentElement.scrollHeight-innerHeight)*100}%`;lastY=y},{passive:true});
$('.menu-toggle').onclick=()=>{const open=$('.mobile-menu').hidden;$('.mobile-menu').hidden=!open;$('.menu-toggle').setAttribute('aria-expanded',String(open));$('.menu-toggle').innerHTML=open?'Close <span>−</span>':'Menu <span>＋</span>';document.body.style.overflow=open?'hidden':''};$$('.mobile-menu a').forEach(a=>a.onclick=()=>$('.menu-toggle').click());addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('.mobile-menu').hidden)$('.menu-toggle').click()});
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const fine=matchMedia('(pointer:fine)').matches;if(fine&&!reduced){addEventListener('pointermove',e=>{const c=$('.cursor');c.style.left=e.clientX+'px';c.style.top=e.clientY+'px';const target=e.target.closest('[data-cursor]');c.classList.toggle('expanded',!!target);c.textContent=target?.dataset.cursor||'';if(scrollY<innerHeight){$('.hero-art').style.transform=`translate(${(e.clientX/innerWidth-.5)*18}px,${(e.clientY/innerHeight-.5)*14}px)`}},{passive:true})}let n=0;const loading=setInterval(()=>{$('.intro-count').textContent=['00','24','57','83','100'][Math.min(n++,4)];if(n>4)clearInterval(loading)},380);
